            if (edges[2*j] == i) adj[i][idx++] = edges[2*j+1];
            if (edges[2*j+1] == i) adj[i][idx++] = edges[2*j];
        }
    }

    // sort vertices by max(a,b)
    qsort(v, n, sizeof(Vertex), cmp);

    // DSU
    int parent[n], sz[n];
    long long sumB[n];
    int minA[n];
    for (int i = 0; i < n; i++) {
        parent[i] = i;
        sz[i] = 1;
        sumB[i] = b[i];
        minA[i] = a[i];
    }

    int active[n];
    for (int i = 0; i < n; i++) active[i] = 0;

    long long ans = 0;

    for (int i = 0; i < n; i++) {
        int u = v[i].idx;
        active[u] = 1;
        // try union with active neighbors
        for (int j = 0; j < deg[u]; j++) {
            int w = adj[u][j];
            if (active[w]) {
                // union find
                int pu = u, pv = w;
                while (parent[pu] != pu) pu = parent[pu];
                while (parent[pv] != pv) pv = parent[pv];
                if (pu != pv) {
                    if (sz[pu] < sz[pv]) { int t=pu; pu=pv; pv=t; }
                    parent[pv] = pu;
                    sz[pu] += sz[pv];
                    sumB[pu] += sumB[pv];
                    if (minA[pv] < minA[pu]) minA[pu] = minA[pv];
                }
            }
        }
        int pu = u;
        while (parent[pu] != pu) pu = parent[pu];
        long long need = minA[pu] - (sumB[pu] - b[u]); // starting money for this component
        if (need > ans) ans = need;
    }

    printf("%lld\n", ans);

    for (int i = 0; i < n; i++) free(adj[i]);
