int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    Node *v = (Node*)malloc((N + 1) * sizeof(Node));
    for (int i = 1; i <= N; i++) scanf("%lld", &v[i].a);
    for (int i = 1; i <= N; i++) scanf("%lld", &v[i].b);

    Edge *edges = (Edge*)malloc((2 * M + 5) * sizeof(Edge));
    int *head = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < M; i++) {
        int x, y;
        scanf("%d %d", &x, &y);
        edges[ecnt].to = y; edges[ecnt].next = head[x]; head[x] = ecnt++;
        edges[ecnt].to = x; edges[ecnt].next = head[y]; head[y] = ecnt++;
    }

    /*
      Key observation:
      To donate to vertex i, current money must be at least A_i, then money changes by +B_i.
      Movement is free along already reachable connected vertices.
      Since graph is connected and donations can be done exactly once per vertex, the only graph
      restriction is that to reach new vertices we need a donated set that is connected to them.
      Starting anywhere is potentially allowed by choosing first donated vertex, so the minimal W
      is the minimal initial money such that there exists an ordering of all vertices where each
      next vertex is adjacent to some previous one (except the first), current money >= A_i, and
      after donation money += B_i.

      A standard sufficient-and-necessary reduction for connected undirected graph:
      Any connected ordering exists for every permutation starting from any root by taking a
      spanning tree order. Thus the graph connectivity does not further constrain feasibility
      beyond connectedness of the whole graph. So we need the minimum initial W such that all
      jobs (A_i, +B_i) can be processed in some order with prerequisite current money >= A_i.

      Optimal strategy:
      - Vertices with B_i >= 0 should be processed as early as possible, by increasing A_i.
      - Vertices with B_i < 0 are processed after nonnegative ones, in decreasing (A_i + B_i).
      This is the classic ordering for tasks with gain/loss and threshold.

      For a fixed order, minimal initial W is:
         W = max over prefixes of (required A at step - gained money before step).
    */

    int *pos = (int*)malloc(N * sizeof(int));
    int *neg = (int*)malloc(N * sizeof(int));
    int pc = 0, nc = 0;
    for (int i = 1; i <= N; i++) {
        if (v[i].b >= 0) pos[pc++] = i;
        else neg[nc++] = i;
    }

    // sort positive by increasing A
    int cmp_pos(const void *p, const void *q) {
        int i = *(const int*)p, j = *(const int*)q;
        if (v[i].a < v[j].a) return -1;
        if (v[i].a > v[j].a) return 1;
        if (v[i].b > v[j].b) return -1;
        if (v[i].b < v[j].b) return 1;
        return 0;
    }

    // sort negative by decreasing A+B
    int cmp_neg(const void *p, const void *q) {
        int i = *(const int*)p, j = *(const int*)q;
        ll xi = v[i].a + v[i].b;
        ll xj = v[j].a + v[j].b;
        if (xi > xj) return -1;
        if (xi < xj) return 1;
        if (v[i].a < v[j].a) return -1;
        if (v[i].a > v[j].a) return 1;
        return 0;
    }

    qsort(pos, pc, sizeof(int), cmp_pos);
    qsort(neg, nc, sizeof(int), cmp_neg);

    ll gain = 0;
    ll ans = 0;

    for (int k = 0; k < pc; k++) {
        int i = pos[k];
        if (v[i].a - gain > ans) ans = v[i].a - gain;
        gain += v[i].b;
    }
    for (int k = 0; k < nc; k++) {
        int i = neg[k];
        if (v[i].a - gain > ans) ans = v[i].a - gain;
        gain += v[i].b;
    }

    if (ans < 0) ans = 0;
    printf("%lld\n", ans);

    free(v);
    free(edges);
    free(head);
    free(pos);
    free(neg);
    return 0;
}

