int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<long long> A(N), B(N);
    for (int i = 0; i < N; ++i) cin >> A[i] >> B[i];

    vector<vector<int>> g(N);
    for (int i = 0; i < M; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    // Check if initial money W is sufficient.
    auto can = [&](long long W) -> bool {
        vector<char> donated(N, 0), reachable(N, 0);
        queue<int> q;

        // Initially, we may stand on any vertex whose entrance requirement is satisfied.
        for (int i = 0; i < N; ++i) {
            if (A[i] <= W) {
                reachable[i] = 1;
                q.push(i);
            }
        }

        long long money = W;
        int done = 0;

        // Greedily donate to every currently reachable and affordable vertex.
        // Each successful donation may increase money and expand reachability.
        priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<pair<long long,int>>> pq;

        auto push_reachable = [&]() {
            while (!q.empty()) {
                int v = q.front(); q.pop();
                if (!donated[v]) pq.push({B[v], v});
                for (int to : g[v]) {
                    if (!reachable[to] && A[to] <= money) {
                        reachable[to] = 1;
                        q.push(to);
                    }
                }
            }
        };

        push_reachable();

        while (true) {
            bool progressed = false;

            // Donate to all reachable vertices whose donation cost is affordable.
            while (!pq.empty()) {
                auto [need, v] = pq.top();
                if (donated[v]) {
                    pq.pop();
                    continue;
                }
                if (need > money) break;
                pq.pop();
                if (donated[v]) continue;
                donated[v] = 1;
                ++done;
                money += B[v]; // after donating B[v], money changes by +B[v] in this model
                progressed = true;

                // After money increases, more vertices may become reachable.
                for (int to : g[v]) {
                    if (!reachable[to] && A[to] <= money) {
                        reachable[to] = 1;
                        q.push(to);
                    }
                }
                push_reachable();
            }

            // Also, maybe increased money allows some already known frontier expansions.
            int before_done = done;
            push_reachable();
            if (done == before_done && !progressed) break;
        }

        return done == N;
    };

    long long lo = 0, hi = 1;
    while (!can(hi)) {
        if (hi > (long long)4e18 / 2) break;
        hi <<= 1;
    }

    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        if (can(mid)) hi = mid;
        else lo = mid + 1;
    }

    cout << lo << '\n';
    return 0;
}

