/*
The statement provided in the prompt is incomplete, but this problem matches the well-known game:

- Connected undirected graph with N vertices, M edges
- Each vertex i has values A[i], B[i]
- Start with money W and may choose any starting vertex
- You can:
  1) Move along edges freely
  2) Donate to a vertex exactly once if current money >= A[i], then money becomes money + B[i]
- Need the minimum initial W such that it is possible to donate to every vertex exactly once.

Key observation:
For a fixed W, consider all vertices currently "available" with A[i] <= current money and connected
through already-donated vertices / chosen starts. Since you may start anywhere, effectively each connected
component of available vertices can be entered at any one available vertex, and then by donating vertices
inside it, your money increases by the sum of B over all vertices in that available connected component.

Thus for a fixed W:
- Initially, vertices with A[i] <= W are "open".
- Open vertices form several connected components in the original graph.
- Entering any open component yields gain = sum(B in that component), so after processing all currently open
  components your money increases by total B of all open vertices.
- This may open more vertices, and the process repeats.

So feasibility for W can be checked by repeatedly activating all vertices with A[i] <= current money and
adding their B once.

We need the minimum W, so binary search.

To process activations efficiently in each check:
- Sort vertices by A.
- Use DSU over activated vertices.
- When a vertex activates, union with already activated neighbors.
- Each DSU root stores sumB of its activated component and whether that component's gain has already been
  collected.
- After all vertices with A <= current money are activated, any newly formed uncollected components can be
  collected once, increasing money.
- Repeat until no more vertices activate.

Complexities:
- Each check: O((N+M) alpha(N))
- Binary search over W in [0, maxA], or more safely [0, maxA] since if W >= maxA all vertices are initially open.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class DSU {
        int[] p, sz;
        long[] sumB;
        boolean[] collected;

        DSU(int n) {
            p = new int[n];
            sz = new int[n];
            sumB = new long[n];
            collected = new boolean[n];
            for (int i = 0; i < n; i++) {
                p[i] = i;
                sz[i] = 1;
            }
        }

        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }

        int union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return a;
            if (sz[a] < sz[b]) {
                int t = a; a = b; b = t;
            }
            p[b] = a;
            sz[a] += sz[b];
            sumB[a] += sumB[b];
            collected[a] = collected[a] || collected[b];
            return a;
        }
    }

    static int N, M;
    static long[] A, B;
    static int[][] edges;
    static ArrayList<Integer>[] g;
    static Integer[] ord;

    static boolean can(long W) {
        DSU dsu = new DSU(N);
        boolean[] active = new boolean[N];
        int idx = 0;
        long money = W;

        while (true) {
            boolean anyActivated = false;
            ArrayList<Integer> newly = new ArrayList<>();

            while (idx < N && A[ord[idx]] <= money) {
                int v = ord[idx++];
                active[v] = true;
                dsu.sumB[v] = B[v];
                newly.add(v);
                anyActivated = true;

                for (int to : g[v]) {
                    if (active[to]) {
                        dsu.union(v, to);
                    }
                }
            }

            if (!anyActivated) break;

            HashSet<Integer> roots = new HashSet<>();
            for (int v : newly) {
                roots.add(dsu.find(v));
                for (int to : g[v]) {
                    if (active[to]) roots.add(dsu.find(to));
                }
            }

            long gain = 0;
            for (int r : roots) {
                r = dsu.find(r);
                if (!dsu.collected[r]) {
                    dsu.collected[r] = true;
                    gain += dsu.sumB[r];
                }
            }
            money += gain;
        }

        return idx == N;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        N = fs.nextInt();
        M = fs.nextInt();

        A = new long[N];
        B = new long[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextLong();
        for (int i = 0; i < N; i++) B[i] = fs.nextLong();

        g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        edges = new int[M][2];
        for (int i = 0; i < M; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            edges[i][0] = u;
            edges[i][1] = v;
            g[u].add(v);
            g[v].add(u);
        }

        ord = new Integer[N];
        long maxA = 0;
        for (int i = 0; i < N; i++) {
            ord[i] = i;
            maxA = Math.max(maxA, A[i]);
        }
        Arrays.sort(ord, Comparator.comparingLong(i -> A[i]));

        long lo = -1, hi = maxA;
        while (hi - lo > 1) {
            long mid = (lo + hi) >>> 1;
            if (can(mid)) hi = mid;
            else lo = mid;
        }

        System.out.println(hi);
    }
